const crypto = require('crypto');

const MAX_SKEW_SECONDS = 300;

const item = $input.first();
const header = String(item.json.headers?.['x-signature'] ?? '');
const parts = Object.fromEntries(header.split(',').map((part) => part.trim().split('=')));
const timestamp = Number(parts.t);
const rawBody = item.binary?.data ? Buffer.from(item.binary.data.data, 'base64').toString('utf8') : '';

const expected = crypto
  .createHmac('sha256', $env.WEBHOOK_SECRET)
  .update(`${parts.t}.${rawBody}`)
  .digest('hex');
const given = String(parts.v1 ?? '');
const fresh = Number.isFinite(timestamp) && Math.abs(Date.now() / 1000 - timestamp) <= MAX_SKEW_SECONDS;
const matches =
  given.length === expected.length && crypto.timingSafeEqual(Buffer.from(given), Buffer.from(expected));
const batchId = String(item.json.body?.batch_id ?? '');
const isUuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(batchId);

return [{ json: { valid: fresh && matches && isUuid, batch_id: batchId } }];

const prompt = "You review Indian personal loan eligibility. A SQL filter has already confirmed every applicant class below meets the\nproduct's numeric rules: income, CIBIL score, age band and employment type. Judge only the product's remaining\nqualitative criteria against each applicant class.\n\n- eligible: the class clearly satisfies the qualitative criteria.\n- likely: the criteria depend on facts the profile does not include, such as work experience or employer category,\n  and nothing in the profile contradicts them.\n- ineligible: something in the profile contradicts the criteria, e.g. age at loan maturity exceeds the limit\n  for the longest tenure, or the income band cannot meet a city- or employer-specific minimum.\n\nGive a reason of at most 18 words written for the applicant. Return one verdict for every class id.";
const schema = {"type": "object", "additionalProperties": false, "required": ["verdicts"], "properties": {"verdicts": {"type": "array", "items": {"type": "object", "additionalProperties": false, "required": ["id", "verdict", "reason"], "properties": {"id": {"type": "integer"}, "verdict": {"type": "string", "enum": ["eligible", "likely", "ineligible"]}, "reason": {"type": "string"}}}}}};
const CLASSES_PER_REQUEST = 20;

const EMPLOYMENT = { salaried: 'Salaried', self_employed: 'Self-employed professional', business: 'Business owner' };
const rupees = (value) => `₹${Number(value).toLocaleString('en-IN')}`;

function describe(classKey) {
  const [employment, income, score, age] = classKey.split('|');
  const incomeFloor = Number(income.slice(3)) * 1000;
  const scoreFloor = Number(score.slice(2));
  const ageFloor = Number(age.slice(3));
  return [
    EMPLOYMENT[employment] ?? employment,
    `net monthly income ${rupees(incomeFloor)}–${rupees(incomeFloor + 24999)}`,
    `CIBIL ${scoreFloor}–${scoreFloor + 49}`,
    `age ${ageFloor}–${ageFloor + 4}`,
  ].join(', ');
}

const rows = $input.all().map((item) => item.json).filter((row) => row.class_key);
const uncached = rows.filter((row) => !row.cached_verdict);

const byProduct = new Map();
for (const row of uncached) {
  if (!byProduct.has(row.product_id)) byProduct.set(row.product_id, []);
  byProduct.get(row.product_id).push(row);
}

const requests = [];
for (const productRows of byProduct.values()) {
  for (let start = 0; start < productRows.length; start += CLASSES_PER_REQUEST) {
    const chunk = productRows.slice(start, start + CLASSES_PER_REQUEST);
    const product = chunk[0];
    const classes = chunk.map((row, index) => `${index + 1}. ${describe(row.class_key)}`).join('\n');
    requests.push({
      product_id: product.product_id,
      product_version: product.product_version,
      class_keys: chunk.map((row) => row.class_key),
      request: {
        model: $env.OPENAI_MODEL,
        temperature: 0,
        response_format: { type: 'json_schema', json_schema: { name: 'class_verdicts', strict: true, schema } },
        messages: [
          { role: 'system', content: prompt },
          {
            role: 'user',
            content:
              `Product: ${product.lender} · ${product.product_name}\n` +
              `Qualitative criteria: ${product.qualitative_criteria}\n\nApplicant classes:\n${classes}`,
          },
        ],
      },
    });
  }
}

return [
  {
    json: {
      stats: {
        classes_to_judge: rows.length,
        cache_hits: rows.length - uncached.length,
        llm_calls: requests.length,
      },
      requests,
    },
  },
];

const MAX_ROUNDS = 4;

const calls =
  $runIndex === 0 ? $('Plan LLM calls').first().json.requests : $('Parse verdicts').last().json.retry;

if ($runIndex >= MAX_ROUNDS) {
  const reason = $('Parse verdicts').last().json.last_error;
  throw new Error(`${calls.length} OpenAI calls still failing after ${MAX_ROUNDS} rounds: ${reason}`);
}

return calls.map((call) => ({ json: call }));

const VERDICTS = new Set(['eligible', 'likely', 'ineligible']);
const FALLBACK_REASON = 'Meets every numeric rule; remaining criteria are checked by the lender.';

const sent = $('Queue judge calls').all(0, $runIndex).map((item) => item.json);
const rows = [];
const retry = [];
let lastError = null;

$input.all().forEach((item, index) => {
  const call = sent[index];
  const content = item.json.choices?.[0]?.message?.content;
  if (!content) {
    retry.push(call);
    lastError = item.json.error?.message ?? item.json.error ?? 'empty response';
    return;
  }
  const answered = new Map((JSON.parse(content).verdicts ?? []).map((verdict) => [verdict.id, verdict]));
  call.class_keys.forEach((classKey, position) => {
    const answer = answered.get(position + 1);
    const valid = answer && VERDICTS.has(answer.verdict) && String(answer.reason ?? '').trim();
    rows.push({
      product_id: call.product_id,
      product_version: call.product_version,
      class_key: classKey,
      verdict: valid ? answer.verdict : 'likely',
      reason: valid ? answer.reason.trim().slice(0, 200) : FALLBACK_REASON,
    });
  });
});

return [{ json: { rows, retry, last_error: lastError } }];
